/* Kept TU-private: the empty default constructor makes RGBA a non-POD, so RgbaFromSpeakerCid returns it through a
   hidden pointer, as in the binary (see the guide's note on tu_15DC80). */
struct RGBA {
    unsigned char r, g, b, a;
    RGBA() {}
    RGBA(int r_, int g_, int b_, int a_) { r = r_; g = g_; b = b_; a = a_; }
};

